module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg  [6:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .y  (y),
        .w  (w),
        .Y1 (Y1),
        .Y3 (Y3)
    );

    integer errors = 0;
    reg [1:0] expected_Y1_Y3;
    integer i, j;

    // Task to check outputs using 4-state case inequality (!==)
    task check_outputs;
        input expected_y1;
        input expected_y3;
        begin
            #1; // Allow combinational propagation
            if ((Y1 !== expected_y1) || (Y3 !== expected_y3)) begin
                $display("Mismatch at time %0t: y=%b, w=%b | Got: Y1=%b, Y3=%b | Expected: Y1=%b, Y3=%b", 
                         $time, y, w, Y1, Y3, expected_y1, expected_y3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        y = 7'b0000000;
        w = 1'b0;
        #10;

        // Test all states (A to F corresponding to y[0] through y[5]) with w = 0 and w = 1
        // State A: y[0] = 1 (y = 7'b0000001)
        // Transitions: A --0--> B (Y1=1), A --1--> A (Y1=0, Y3=0)
        y = 7'b0000001; w = 0; check_outputs(1'b1, 1'b0);
        y = 7'b0000001; w = 1; check_outputs(1'b0, 1'b0);

        // State B: y[1] = 1 (y = 7'b0000010)
        // Transitions: B --0--> C (Y1=0, Y3=0), B --1--> D (Y1=0, Y3=1)
        y = 7'b0000010; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b0000010; w = 1; check_outputs(1'b0, 1'b1);

        // State C: y[2] = 1 (y = 7'b0000100)
        // Transitions: C --0--> E (Y1=0, Y3=0), C --1--> D (Y1=0, Y3=1)
        y = 7'b0000100; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b0000100; w = 1; check_outputs(1'b0, 1'b1);

        // State D: y[3] = 1 (y = 7'b0001000)
        // Transitions: D --0--> F (Y1=0, Y3=0), D --1--> A (Y1=0, Y3=0)
        y = 7'b0001000; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b0001000; w = 1; check_outputs(1'b0, 1'b0);

        // State E: y[4] = 1 (y = 7'b0010000)
        // Transitions: E --0--> E (Y1=0, Y3=0), E --1--> D (Y1=0, Y3=1)
        y = 7'b0010000; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b0010000; w = 1; check_outputs(1'b0, 1'b1);

        // State F: y[5] = 1 (y = 7'b0100000)
        // Transitions: F --0--> C (Y1=0, Y3=0), F --1--> D (Y1=0, Y3=1)
        y = 7'b0100000; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b0100000; w = 1; check_outputs(1'b0, 1'b1);

        // Unused states / bit patterns (e.g., y[6] or multiple bits set)
        y = 7'b1000000; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b1000000; w = 1; check_outputs(1'b0, 1'b0);
        y = 7'b0000000; w = 1; check_outputs(1'b0, 1'b0);

        // Final Result Evaluation
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
